public class Main {

    public static void main(String[] args) throws Exception {
        var count=new java.util.concurrent.atomic.AtomicInteger();Thread worker=new Thread(()->{for(int i=0;i<3;i++)count.incrementAndGet();});worker.start();worker.join();System.out.println(0);
    }
}

public class Main {

    public static void main(String[] args) throws Exception {
        var barrier=new java.util.concurrent.CyclicBarrier(2);var count=new java.util.concurrent.atomic.AtomicInteger();Runnable job=()->{int before=count.get();try{barrier.await();}catch(Exception e){throw new RuntimeException(e);}count.set(before+1);};Thread a=new Thread(job), b=new Thread(job);a.start();b.start();a.join();b.join();System.out.println(count.get());
    }
}

public class Main {

    public static void main(String[] args) throws Exception {
        var in = new java.util.Scanner(System.in); int n=in.nextInt();var count=new java.util.concurrent.atomic.AtomicInteger();Runnable job=()->{for(int i=0;i<n;i++)/* 完成原子增加 */};Thread a=new Thread(job), b=new Thread(job);a.start();b.start();a.join();b.join();System.out.println(count.get());
    }
}

